<?php
$edit=null;if(isset($_GET['edit'])){$s=db()->prepare('SELECT * FROM clients WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch()?:null;}
$rows=db()->query("SELECT c.*,m.end_date,m.status membership_status,p.name plan_name FROM clients c LEFT JOIN memberships m ON m.id=(SELECT id FROM memberships WHERE client_id=c.id ORDER BY id DESC LIMIT 1) LEFT JOIN plans p ON p.id=m.plan_id WHERE c.active=1 ORDER BY c.created_at DESC")->fetchAll();
?>
<section class="card panel <?=isset($_GET['new'])||$edit?'':'hidden'?>" id="client-form"><div class="panel-head"><h2><?= $edit?'Editar cliente':'Registrar cliente' ?></h2><button class="link-btn" onclick="this.closest('.panel').classList.add('hidden')">Cerrar ×</button></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="client_save"><input type="hidden" name="id" value="<?=h((string)($edit['id']??''))?>"><input type="hidden" name="return_view" value="clients"><label>Nombre completo<input name="name" required value="<?=h($edit['name']??'')?>"></label><label>Correo electrónico<input name="email" type="email" required value="<?=h($edit['email']??'')?>"></label><label>Teléfono<input name="phone" value="<?=h($edit['phone']??'')?>"></label><label>Documento / CI<input name="document_number" value="<?=h($edit['document_number']??'')?>"></label><label>Fecha de nacimiento<input name="birth_date" type="date" value="<?=h($edit['birth_date']??'')?>"></label><label>Notas<input name="notes" value="<?=h($edit['notes']??'')?>"></label><?php if(!$edit): ?><label>Contraseña para portal del cliente (opcional)<input type="password" name="portal_password" minlength="10" placeholder="10 caracteres o más"><small class="muted">Al definirla, el cliente podrá iniciar sesión.</small></label><?php endif; ?><div class="form-actions"><button type="reset" class="btn">Limpiar</button><button class="btn primary">Guardar cliente</button></div></form></section>
<section class="card panel"><div class="panel-head"><h2>Directorio de clientes <small>(<?=count($rows)?>)</small></h2><input class="search" data-search="#clients-table" placeholder="Buscar por nombre, correo o CI…"></div><div class="table-wrap"><table id="clients-table"><thead><tr><th>CLIENTE</th><th>CONTACTO</th><th>MEMBRESÍA</th><th>VENCIMIENTO</th><th>ESTADO</th><th></th></tr></thead><tbody><?php foreach($rows as $r): $state=$r['membership_status']==='active'&&$r['end_date']>=date('Y-m-d'); ?><tr><td><div class="person"><span class="mini-avatar"><?=h(mb_substr($r['name'],0,1))?></span><?=h($r['name'])?></div><small class="muted"><?=h($r['document_number']?:'Sin CI')?></small></td><td><?=h($r['email'])?><br><small class="muted"><?=h($r['phone']?:'Sin teléfono')?></small></td><td><?=h($r['plan_name']??'—')?></td><td><?= $r['end_date']?date('d/m/Y',strtotime($r['end_date'])):'—' ?></td><td><span class="pill <?=$state?'':'expired'?>"><?=$state?'Activa':'Sin vigencia'?></span></td><td><div class="actions"><button class="link-btn" data-edit-client='<?=h(json_encode(['id'=>$r['id'],'name'=>$r['name'],'email'=>$r['email'],'phone'=>$r['phone'],'document_number'=>$r['document_number'],'birth_date'=>$r['birth_date'],'notes'=>$r['notes']],JSON_HEX_APOS|JSON_HEX_QUOT))?>'>Editar</button><form method="post" data-confirm="¿Desactivar este cliente?" style="display:inline"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="client_delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="link-btn">Desactivar</button></form></div></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6" class="empty">Todavía no hay clientes. Registra el primero.</td></tr><?php endif; ?></tbody></table></div></section>
